@@ -212,7 +212,7 @@ async function subtestBadAccessToken(identity, outgoingServer) {
   expiredModule.initFromOutgoing(outgoingServer);
   await expiredModule._oauth.connect(false, false);

-  OAuth2TestUtils.invalidateToken("bad_access_token");
+  OAuth2TestUtils.revokeToken("bad_access_token");

   const { composeWindow } = await newComposeWindow(identity);

diff --git a/mailnews/test/resources/OAuth2TestUtils.sys.mjs b/mailnews/test/resources/OAuth2TestUtils.sys.mjs
index 1cd4d186ff5..0e9566f5f84 100644
--- a/mailnews/test/resources/OAuth2TestUtils.sys.mjs
+++ b/mailnews/test/resources/OAuth2TestUtils.sys.mjs
@@ -156,7 +156,7 @@ export const OAuth2TestUtils = {
    *
    * @param {string} token
    */
-  invalidateToken(token) {
+  revokeToken(token) {
     tokens.delete(token);
   },
